{
  "schemaVersion": 1,
  "id": "parker.drawer",
  "name": "Drawer",
  "version": "1.0.0",
  "author": "parker",
  "description": "Bar button that opens a panel holding the bar widgets you tuck away",
  "kinds": [
    "bar-widget"
  ],
  "entryPoints": {
    "barWidget": "Drawer.qml"
  },
  "barWidget": {
    "displayName": "Drawer",
    "description": "Click to show tucked-away bar widgets",
    "category": "Layout",
    "allowMultiple": true,
    "defaultSection": "right",
    "defaults": {
      "icon": "󰅀",
      "iconOpen": "󰅃",
      "tooltip": "Drawer",
      "items": []
    }
  }
}

import QtQuick
import Quickshell
import Quickshell.Io
import Quickshell.Wayland
import Quickshell.Hyprland
import qs.Commons
import qs.Ui

// Drawer: a bar button that opens a strip holding the bar widgets listed in
// this entry's `items` in ~/.config/omarchy/shell.json, e.g.
//
//   { "id": "parker.drawer",
//     "items": [ "omarchy.weather", { "id": "omarchy.clock", "format": "HH:mm" } ] }
//
// Items are plain widget ids or full layout entries (id + inline settings),
// so an entry can be moved from bar.layout into the drawer unchanged.
//
// Hosted widgets are loaded from their plugin's barWidget entry point and get
// `hostBar`, a stand-in for the bar that forwards to this widget's own bar
// facade except for popouts (coordinated inside the drawer, so opening a
// hosted panel does not close the drawer), tooltips (drawn here, since the
// bar only draws tooltips for its own window) and settings writes (stored
// back into this entry's `items`).
BarWidget {
  id: root

  // ---- configuration -------------------------------------------------------

  readonly property var items: normalizeItems(setting("items", []))
  readonly property string closedIcon: String(setting("icon", "󰅀"))
  readonly property string openIcon: String(setting("iconOpen", "󰅃"))
  readonly property string tooltip: String(setting("tooltip", "Drawer"))

  readonly property string omarchyPath: Quickshell.env("OMARCHY_PATH") || "/usr/share/omarchy"
  readonly property string home: Quickshell.env("HOME") || ""

  // id -> file URL of that plugin's barWidget entry point.
  property var widgetUrls: ({})
  property bool resolved: false
  // Ids in display order. Only reassigned when the id list really changes,
  // so a settings-only change (e.g. a hosted clock saving its format) updates
  // the hosted widget in place instead of rebuilding every widget.
  property var itemIds: []

  // ---- popout state ---------------------------------------------------------

  property bool drawerOpen: false
  // Popout owner of whichever hosted widget has its panel open, if any.
  property var hostedPopout: null
  property var hostedSlots: []

  // Shape the bar's popout coordinator and `omarchy-shell shell toggle
  // parker.drawer` look for: open / close / opened on the widget root.
  readonly property bool opened: drawerOpen
  readonly property bool popoutSwitchClosing: false

  readonly property var barWindow: button.QsWindow.window

  implicitWidth: button.implicitWidth
  implicitHeight: button.implicitHeight

  function normalizeItems(raw) {
    var out = []
    if (!Array.isArray(raw)) return out
    for (var i = 0; i < raw.length; i++) {
      var it = raw[i]
      if (typeof it === "string" && it.trim() !== "") out.push({ id: it.trim() })
      else if (it && typeof it === "object" && !Array.isArray(it) && typeof it.id === "string" && it.id !== "") out.push(it)
    }
    return out
  }

  function entrySettings(entry) {
    var copy = {}
    for (var key in entry) if (key !== "id") copy[key] = entry[key]
    return copy
  }

  function syncItemIds() {
    var ids = items.map(function(e) { return e.id })
    if (JSON.stringify(ids) !== JSON.stringify(itemIds)) itemIds = ids
    // A newly listed id may belong to a plugin installed since the last scan.
    for (var i = 0; i < ids.length; i++) {
      if (resolved && !widgetUrls[ids[i]] && !resolver.running) { resolver.running = true; break }
    }
  }

  onItemsChanged: syncItemIds()
  Component.onCompleted: {
    syncItemIds()
    resolver.running = true
  }

  // ---- open / close -------------------------------------------------------

  function open() {
    if (drawerOpen) return
    drawerOpen = true
    if (bar) bar.requestPopout(root)
  }

  function close() {
    closeHosted()
    tooltipState.clear()
    if (!drawerOpen) return
    drawerOpen = false
    if (bar && bar.activePopout === root) bar.releasePopout(root)
  }

  function closeForPopoutSwitch() { close() }
  function toggle() { drawerOpen ? close() : open() }

  function closeHosted() {
    var owner = hostedPopout
    if (!owner) return
    if ("close" in owner) owner.close()
    if (hostedPopout === owner) hostedPopout = null
  }

  // Mirrors Bar.requestPopout, scoped to the widgets in this drawer.
  function requestHostedPopout(owner) {
    if (!owner || hostedPopout === owner) return
    if (!drawerOpen) open()
    var previous = hostedPopout
    if (previous) {
      if ("closeForPopoutSwitch" in previous) previous.closeForPopoutSwitch()
      else if ("close" in previous) previous.close()
    }
    hostedPopout = owner
  }

  function releaseHostedPopout(owner) {
    if (hostedPopout === owner) hostedPopout = null
  }

  function hostedWidgets(id) {
    var out = []
    for (var i = 0; i < hostedSlots.length; i++) {
      var slot = hostedSlots[i]
      if (slot && slot.hosted && (!id || slot.modelData === id)) out.push(slot.hosted)
    }
    return out
  }

  // Left/right in a hosted panel moves to the next hosted widget with a panel.
  function switchHostedPanel(owner, direction) {
    var panels = hostedWidgets("").filter(function(w) {
      return w.visible && typeof w.open === "function" && typeof w.close === "function" && w.opened !== undefined
    })
    var index = panels.indexOf(owner)
    if (index < 0 || panels.length < 2) return false
    var next = panels[(index + (direction < 0 ? -1 : 1) + panels.length) % panels.length]
    next.open()
    return true
  }

  // Store a hosted widget's settings back into this entry's `items`.
  function updateItemSettings(id, settings) {
    if (!bar || !bar.shell || typeof bar.shell.updateEntryInline !== "function") return false
    var mine = entrySettings(root.settings || {})
    var list = Array.isArray(mine.items) ? mine.items.slice() : []
    for (var i = 0; i < list.length; i++) {
      var current = list[i]
      var currentId = typeof current === "string" ? current : (current && current.id)
      if (currentId !== id) continue
      var next = { id: id }
      for (var key in settings) if (key !== "id") next[key] = settings[key]
      list[i] = next
      mine.items = list
      return bar.shell.updateEntryInline(root.moduleName, mine)
    }
    return false
  }

  onBarChanged: if (!bar) close()

  // Another bar panel taking over closes the drawer through close(); this
  // also catches the bar being rebuilt underneath an open drawer.
  Connections {
    target: root.bar
    ignoreUnknownSignals: true
    function onActivePopoutChanged() {
      if (root.drawerOpen && root.bar && root.bar.activePopout !== root && !root.hostedPopout) root.close()
    }
  }

  // ---- widget id -> entry point --------------------------------------------

  // Read every bar-widget manifest: stock plugins first, then the user's own
  // plugins, so a clone (or a third-party widget) wins on an id clash.
  Process {
    id: resolver
    command: ["bash", "-c", `
      shopt -s nullglob
      for f in "$1"/shell/plugins/*/manifest.json "$1"/shell/plugins/*/*/manifest.json \\
               "$1"/shell/plugins/*/*.manifest.json "$1"/shell/plugins/*/*/*.manifest.json \\
               "$2"/.config/omarchy/plugins/*/manifest.json; do
        jq -r --arg d "\${f%/*}" '
          select(((.kinds // []) | index("bar-widget")) and ((.entryPoints.barWidget // null) | type) == "string")
          | [.id, $d + "/" + .entryPoints.barWidget] | @tsv' "$f" 2>/dev/null
      done
    `, "drawer-resolve", root.omarchyPath, root.home]
    stdout: StdioCollector {
      onStreamFinished: {
        var map = {}
        var lines = String(text || "").split("\n")
        for (var i = 0; i < lines.length; i++) {
          var parts = lines[i].split("\t")
          if (parts.length !== 2 || !parts[0] || parts[1].indexOf("/") !== 0) continue
          map[parts[0]] = "file://" + parts[1]
        }
        root.widgetUrls = map
        root.resolved = true
      }
    }
  }

  // ---- the bar button -------------------------------------------------------

  BarIconButton {
    id: button
    anchors.fill: parent
    bar: root.bar
    text: root.drawerOpen ? root.openIcon : root.closedIcon
    slotSize: Style.bar.statusSlot
    tooltipText: root.drawerOpen ? "" : root.tooltip
    onPressed: function(b) {
      if (b === Qt.LeftButton || b === Qt.MiddleButton) root.toggle()
    }
  }

  // ---- what hosted widgets see as their bar ------------------------------

  QtObject {
    id: hostShell

    readonly property var barConfig: root.bar && root.bar.shell ? root.bar.shell.barConfig : ({})
    readonly property var bar: root.bar && root.bar.shell ? root.bar.shell.bar : null

    function serviceFor(id) { return root.bar && root.bar.shell ? root.bar.shell.serviceFor(id) : null }
    function firstPartyServiceFor(id) {
      return root.bar && root.bar.shell && typeof root.bar.shell.firstPartyServiceFor === "function"
        ? root.bar.shell.firstPartyServiceFor(id) : null
    }
    function summon(id, payload) { return root.bar && root.bar.shell ? root.bar.shell.summon(id, payload) : false }
    function hide(id) { return root.bar && root.bar.shell ? root.bar.shell.hide(id) : false }
    function toggle(id, payload) { return root.bar && root.bar.shell ? root.bar.shell.toggle(id, payload) : false }
    function isPluginOpen(id) { return root.bar && root.bar.shell ? root.bar.shell.isPluginOpen(id) : false }
    function updateEntryInline(id, settings) { return root.updateItemSettings(String(id || ""), settings || {}) }
    function mutateShellConfig(mutator) { return false }
  }

  QtObject {
    id: hostBar

    readonly property color foreground: root.bar ? root.bar.foreground : Color.foreground
    readonly property color barForeground: foreground
    readonly property color background: Color.popups.background
    readonly property color urgent: root.bar ? root.bar.urgent : Color.urgent
    readonly property string fontFamily: root.bar ? root.bar.fontFamily : Style.font.family
    readonly property string position: root.bar ? root.bar.position : "top"
    readonly property bool vertical: root.bar ? root.bar.vertical : false
    readonly property int barSize: root.bar ? root.bar.barSize : Style.bar.sizeHorizontal
    readonly property bool transparent: false
    readonly property bool foregroundAnimationEnabled: true
    readonly property bool centerSectionRevealHeld: true
    readonly property bool centerHoverRevealSuppressed: false
    readonly property var activePopout: root.hostedPopout
    readonly property var clickTargets: root.bar ? root.bar.clickTargets : []
    readonly property var layoutConfig: root.bar ? root.bar.layoutConfig : ({})
    readonly property var shell: hostShell

    function run(command) { if (root.bar) root.bar.run(command) }
    function shellQuote(value) { return "'" + String(value).replace(/'/g, "'\\''") + "'" }
    function showTooltip(target, text) { tooltipState.show(target, text) }
    function hideTooltip(target) { tooltipState.hide(target) }
    function registerClickTarget(target) { if (root.bar) root.bar.registerClickTarget(target) }
    function unregisterClickTarget(target) { if (root.bar) root.bar.unregisterClickTarget(target) }
    function requestPopout(owner) { root.requestHostedPopout(owner) }
    function releasePopout(owner) { root.releaseHostedPopout(owner) }
    function switchPanelFrom(owner, direction) { return root.switchHostedPanel(owner, direction) }
    function targetBelongsToWindow(target, window) {
      return root.bar ? root.bar.targetBelongsToWindow(target, window) : false
    }
    function moduleWidgets(id) { return root.hostedWidgets(String(id || "")) }
    function setCenterHoverRevealSuppressed(value) {}
  }

  QtObject {
    id: tooltipState

    property var target: null
    property string text: ""
    property bool shown: false

    function show(t, s) {
      clear()
      if (!t || !s) return
      target = t
      text = String(s)
      tooltipTimer.restart()
    }
    function hide(t) { if (target === t) clear() }
    function clear() {
      tooltipTimer.stop()
      shown = false
      target = null
      text = ""
    }
  }

  Timer {
    id: tooltipTimer
    interval: 400
    onTriggered: tooltipState.shown = !!tooltipState.target && tooltipState.target.tooltipHovered === true
  }

  // ---- the drawer surface -------------------------------------------------

  // Spans from the screen edge across the bar to the far side of the card.
  // Hosted widgets' own panels place themselves past the edge of the window
  // their button sits in, so this extent puts them just beyond the drawer.
  // Only the card takes input; the part over the bar is click-through.
  PanelWindow {
    id: drawerWindow

    readonly property string pos: hostBar.position
    readonly property bool sideBar: pos === "left" || pos === "right"
    readonly property real barW: root.barWindow ? root.barWindow.width : hostBar.barSize
    readonly property real barH: root.barWindow ? root.barWindow.height : hostBar.barSize
    readonly property int gap: Style.gapsOut
    readonly property int margin: Style.gapsOut
    readonly property real screenW: screen ? screen.width : 0
    readonly property real screenH: screen ? screen.height : 0

    screen: root.barWindow ? root.barWindow.screen : null
    visible: root.drawerOpen || card.opacity > 0
    color: "transparent"
    exclusionMode: ExclusionMode.Ignore
    WlrLayershell.namespace: "parker-drawer"
    WlrLayershell.layer: WlrLayer.Top
    WlrLayershell.keyboardFocus: root.drawerOpen && !root.hostedPopout ? WlrKeyboardFocus.OnDemand : WlrKeyboardFocus.None

    anchors {
      top: drawerWindow.pos !== "bottom"
      bottom: drawerWindow.pos !== "top"
      left: drawerWindow.pos !== "right"
      right: drawerWindow.pos !== "left"
    }
    implicitWidth: sideBar ? Math.ceil(barW + gap + card.width) : 0
    implicitHeight: sideBar ? 0 : Math.ceil(barH + gap + card.height)

    mask: Region { item: card }

    // Click outside the drawer (and outside the bar) closes it. Suspended
    // while a hosted panel is open: that panel dismisses itself first.
    HyprlandFocusGrab {
      active: root.drawerOpen && !root.hostedPopout && !!root.barWindow
      windows: root.barWindow ? [drawerWindow, root.barWindow] : [drawerWindow]
      onCleared: root.close()
    }

    TransformWatcher {
      id: anchorWatcher
      a: root.barWindow ? root.barWindow.contentItem : null
      b: button
    }

    readonly property point buttonPos: {
      anchorWatcher.transform
      if (!root.barWindow) return Qt.point(0, 0)
      return button.mapToItem(root.barWindow.contentItem, 0, 0)
    }

    BorderSurface {
      id: card

      readonly property int pad: Style.spacing.sm

      x: {
        if (drawerWindow.pos === "left") return drawerWindow.barW + drawerWindow.gap
        if (drawerWindow.pos === "right") return 0
        var want = drawerWindow.buttonPos.x + button.width / 2 - width / 2
        return Math.round(Math.max(drawerWindow.margin, Math.min(want, drawerWindow.screenW - width - drawerWindow.margin)))
      }
      y: {
        if (drawerWindow.pos === "top") return drawerWindow.barH + drawerWindow.gap
        if (drawerWindow.pos === "bottom") return 0
        var want = drawerWindow.buttonPos.y + button.height / 2 - height / 2
        return Math.round(Math.max(drawerWindow.margin, Math.min(want, drawerWindow.screenH - height - drawerWindow.margin)))
      }
      width: Math.ceil(content.implicitWidth + pad * 2 + Border.left(borderSpec) + Border.right(borderSpec))
      height: Math.ceil(content.implicitHeight + pad * 2 + Border.top(borderSpec) + Border.bottom(borderSpec))
      color: Color.popups.background
      borderSpec: Border.surfaceSpec("popups", "border", Color.popups.border, Math.max(1, Style.space(2)))
      radius: Style.cornerRadius
      opacity: root.drawerOpen ? 1 : 0

      Behavior on opacity {
        NumberAnimation { duration: 140; easing.type: Easing.OutCubic }
      }

      Item {
        anchors.fill: parent
        focus: root.drawerOpen
        Keys.onEscapePressed: root.close()
      }

      Grid {
        id: content
        anchors.centerIn: parent
        flow: hostBar.vertical ? Grid.TopToBottom : Grid.LeftToRight
        columns: hostBar.vertical ? 1 : Math.max(1, root.itemIds.length + 1)
        rows: hostBar.vertical ? Math.max(1, root.itemIds.length + 1) : 1
        spacing: 0

        Repeater {
          model: root.itemIds

          Item {
            id: slot

            required property string modelData
            required property int index

            readonly property var entry: root.items[index] && root.items[index].id === modelData
              ? root.items[index] : ({ id: modelData })
            readonly property var entrySettings: root.entrySettings(entry)
            readonly property string url: root.widgetUrls[modelData] || ""
            readonly property bool missing: root.resolved && url === ""
            readonly property Item hosted: loader.item
            readonly property bool shows: !!hosted && hosted.visible

            implicitWidth: shows ? (hostBar.vertical ? hostBar.barSize : hosted.implicitWidth)
              : (missing ? missingLabel.implicitWidth + Style.spacing.md * 2 : 0)
            implicitHeight: shows ? (hostBar.vertical ? hosted.implicitHeight : hostBar.barSize)
              : (missing ? hostBar.barSize : 0)
            width: implicitWidth
            height: implicitHeight

            function inject() {
              var item = loader.item
              if (!item) return
              if ("bar" in item) item.bar = hostBar
              if ("moduleName" in item) item.moduleName = slot.modelData
              if ("settings" in item) item.settings = slot.entrySettings
            }

            onEntrySettingsChanged: inject()
            Component.onCompleted: root.hostedSlots = root.hostedSlots.concat([slot])
            Component.onDestruction: {
              if (loader.item && root.hostedPopout === loader.item) root.hostedPopout = null
              root.hostedSlots = root.hostedSlots.filter(function(s) { return s !== slot })
            }

            Loader {
              id: loader
              anchors.fill: parent
              active: slot.url !== ""
              source: slot.url
              onLoaded: {
                slot.inject()
                Qt.callLater(slot.inject)
              }
              onStatusChanged: if (status === Loader.Error) console.warn("parker.drawer: could not load " + slot.modelData + " from " + slot.url)
            }

            // An id that matches no installed bar widget shows up here
            // instead of disappearing silently, so typos are visible.
            Text {
              id: missingLabel
              anchors.centerIn: parent
              visible: slot.missing
              text: "? " + slot.modelData
              color: Color.muted
              font.family: hostBar.fontFamily
              font.pixelSize: Style.bar.iconFont * 0.8
            }
          }
        }

        Text {
          readonly property bool empty: root.hostedSlots.every(function(s) { return !s || s.width <= 0 })
          visible: empty
          width: visible ? implicitWidth + Style.spacing.md * 2 : 0
          height: visible ? hostBar.barSize : 0
          horizontalAlignment: Text.AlignHCenter
          verticalAlignment: Text.AlignVCenter
          text: root.itemIds.length === 0 ? "Drawer is empty: add ids to \"items\"" : "Nothing to show"
          color: Color.muted
          font.family: hostBar.fontFamily
          font.pixelSize: Style.bar.iconFont * 0.8
        }
      }
    }

    PopupWindow {
      id: tooltipWindow

      readonly property var target: tooltipState.target

      visible: root.drawerOpen && tooltipState.shown && !!target && tooltipState.text !== ""
      color: "transparent"
      implicitWidth: Math.ceil(bubble.implicitWidth)
      implicitHeight: Math.ceil(bubble.implicitHeight)

      anchor {
        id: tooltipAnchor
        window: drawerWindow
        adjustment: PopupAdjustment.Slide
        edges: Edges.Top | Edges.Left
        gravity: Edges.Bottom | Edges.Right
        rect.width: 1
        rect.height: 1

        onAnchoring: {
          var t = tooltipWindow.target
          if (!t) return
          var w = tooltipWindow.implicitWidth
          var h = tooltipWindow.implicitHeight
          var lx = t.width / 2 - w / 2, ly = t.height + 6
          if (drawerWindow.pos === "bottom") ly = -h - 6
          else if (drawerWindow.pos === "left") { lx = t.width + 6; ly = t.height / 2 - h / 2 }
          else if (drawerWindow.pos === "right") { lx = -w - 6; ly = t.height / 2 - h / 2 }
          var p = drawerWindow.contentItem.mapFromItem(t, lx, ly)
          tooltipAnchor.rect.x = Math.round(p.x)
          tooltipAnchor.rect.y = Math.round(p.y)
        }
      }

      BorderSurface {
        id: bubble
        implicitWidth: tipLabel.implicitWidth + 20
        implicitHeight: tipLabel.implicitHeight + 10
        anchors.fill: parent
        color: Color.tooltip.background
        borderSpec: Border.flat(Color.tooltip.border, 1)
        radius: Style.cornerRadius

        Text {
          id: tipLabel
          anchors.centerIn: parent
          text: tooltipState.text
          color: Color.tooltip.text
          font.family: hostBar.fontFamily
          font.pixelSize: Style.bar.iconFont * 0.8
        }
      }
    }
  }
}

